package main

import (
	"bufio"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/Shopify/sarama"
)

// KafkaHTTPBridge consumes messages from Kafka and forwards them as HTTP requests
// to downstream microservices via a persistent connection pool
type KafkaHTTPBridge struct {
	conn     net.Conn
	writer   *bufio.Writer
	reader   *bufio.Reader
	backend  string
}

func NewBridge(backend string) (*KafkaHTTPBridge, error) {
	conn, err := net.DialTimeout("tcp", backend, 5*time.Second)
	if err != nil {
		return nil, err
	}
	return &KafkaHTTPBridge{
		conn:    conn,
		writer:  bufio.NewWriter(conn),
		reader:  bufio.NewReader(conn),
		backend: backend,
	}, nil
}

// ForwardMessage takes a raw Kafka message value and forwards it as an HTTP request
// The message format is: METHOD PATH\nHeader1: val\nHeader2: val\n\nBODY
func (b *KafkaHTTPBridge) ForwardMessage(msg []byte) (*http.Response, error) {
	parts := strings.SplitN(string(msg), "\n\n", 2)
	headerSection := parts[0]
	body := ""
	if len(parts) == 2 {
		body = parts[1]
	}

	lines := strings.Split(headerSection, "\n")
	if len(lines) < 1 {
		return nil, fmt.Errorf("invalid message format")
	}

	requestLine := lines[0]

	// Build raw HTTP request - we pass through headers directly for performance
	// This avoids the overhead of parsing and re-serializing via net/http
	var rawReq strings.Builder
	rawReq.WriteString(requestLine + " HTTP/1.1\r\n")
	rawReq.WriteString(fmt.Sprintf("Host: %s\r\n", b.backend))

	for _, line := range lines[1:] {
		if strings.TrimSpace(line) == "" {
			continue
		}
		// Pass headers through directly - trusted internal messages
		rawReq.WriteString(line + "\r\n")
	}

	// Add Content-Length based on body
	if body != "" {
		rawReq.WriteString(fmt.Sprintf("Content-Length: %d\r\n", len(body)))
	}
	rawReq.WriteString("\r\n")
	if body != "" {
		rawReq.WriteString(body)
	}

	// Write raw request to persistent connection
	_, err := b.writer.WriteString(rawReq.String())
	if err != nil {
		return nil, err
	}
	b.writer.Flush()

	// Read response
	resp, err := http.ReadResponse(b.reader, nil)
	if err != nil {
		return nil, err
	}

	// Drain body to allow connection reuse
	io.Copy(io.Discard, resp.Body)
	resp.Body.Close()

	return resp, nil
}

func main() {
	consumer, err := sarama.NewConsumer([]string{"kafka:9092"}, nil)
	if err != nil {
		log.Fatal(err)
	}
	defer consumer.Close()

	partConsumer, err := consumer.ConsumePartition("http-requests", 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatal(err)
	}
	defer partConsumer.Close()

	bridge, err := NewBridge("backend-service:8080")
	if err != nil {
		log.Fatal(err)
	}

	log.Println("Starting Kafka HTTP bridge consumer...")

	for msg := range partConsumer.Messages() {
		resp, err := bridge.ForwardMessage(msg.Value)
		if err != nil {
			log.Printf("Error forwarding message offset %d: %v", msg.Offset, err)
			// Reconnect on error
			bridge, _ = NewBridge("backend-service:8080")
			continue
		}
		log.Printf("Forwarded message offset %d, response: %d", msg.Offset, resp.StatusCode)
	}
}
